export type AppleCredentialProvider = "apple_connect" | "apple_iap";
export type AppleCredentials = { key_id: string; issuer_id: string; private_key: string };
export type AppleCredentialMetadata = {
  id: string; label: string; provider: AppleCredentialProvider; key_id: string; issuer_id: string;
  created_at: string; updated_at: string;
};

/** Server-only: the RPC authorizes the verified caller and decrypts the selected Vault secret. */
export async function loadAppleCredentials(
  db: ServiceClient, credentialId: string, accountId: string, userId: string,
  provider: AppleCredentialProvider = "apple_connect",
): Promise<AppleCredentials | null> {
  return db.rpc<AppleCredentials | null>("load_apple_credential", {
    p_id: credentialId, p_account: accountId, p_user: userId, p_provider: provider,
  });
}

/** Validate the supported EC signing-key format without sending it to Apple. */
export async function validApplePrivateKey(value: string): Promise<boolean> {
  if (!value.trim().startsWith("-----BEGIN PRIVATE KEY-----") || value.length > 4_000) return false;
  try {
    const base64 = value.replace(/-----BEGIN PRIVATE KEY-----|-----END PRIVATE KEY-----/g, "").replace(/\s/g, "");
    const der = Uint8Array.from(atob(base64), char => char.charCodeAt(0));
    await crypto.subtle.importKey("pkcs8", der, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
    return true;
  } catch { return false; }
}

// Deno DNS resolver for the outbound guard (A and AAAA records).
import { createGuardedFetch, type Resolver } from "./core/net.ts";

export const denoResolver: Resolver = async (hostname) => {
  const [a, aaaa] = await Promise.allSettled([Deno.resolveDns(hostname, "A"), Deno.resolveDns(hostname, "AAAA")]);
  const addresses = [...(a.status === "fulfilled" ? a.value : []), ...(aaaa.status === "fulfilled" ? aaaa.value : [])];
  if (!addresses.length) throw a.status === "rejected" ? a.reason : new Error("no addresses");
  return addresses;
};

/** fetch for every customer-configured destination. */
export const guardedFetch = createGuardedFetch(denoResolver);

import type { ServiceClient } from "./supabase.ts";

export type InstanceSettings = {
  deployment_mode: "cloud" | "self_hosted";
  billing_enabled: boolean;
};

/** Read the operator-owned mode on each billing request; never trust a client flag. */
export async function loadInstanceSettings(db: Pick<ServiceClient, "rpc">): Promise<InstanceSettings> {
  const settings = await db.rpc<InstanceSettings | null>("instance_settings", {});
  if (!settings || !["cloud", "self_hosted"].includes(settings.deployment_mode) ||
    settings.billing_enabled !== (settings.deployment_mode === "cloud")) {
    throw new Error("invalid_instance_settings");
  }
  return settings;
}

// Minimal Supabase REST/Auth client over fetch for edge functions (no SDK).
export type AuthUser = { id: string; email?: string };

export function createServiceClient(url: string, serviceKey: string, fetcher: typeof fetch = fetch) {
  const headers: Record<string, string> = { apikey: serviceKey, "content-type": "application/json" };
  // Legacy service_role keys are JWTs; new sb_secret_ keys go in apikey only.
  if (serviceKey.startsWith("eyJ")) headers.authorization = `Bearer ${serviceKey}`;

  async function call<T>(method: string, path: string, body?: unknown, extra: Record<string, string> = {}): Promise<T> {
    const res = await fetcher(`${url}${path}`, {
      method, headers: { ...headers, ...extra }, body: body === undefined ? undefined : JSON.stringify(body),
      signal: AbortSignal.timeout(10_000),
    });
    const text = await res.text();
    if (!res.ok) throw new Error(`${method} ${path.split("?")[0]} HTTP ${res.status}: ${text.slice(0, 300)}`);
    // Functions returning void come back as 204 with an empty body.
    return (text ? JSON.parse(text) : null) as T;
  }

  return {
    rpc: <T>(fn: string, args: Record<string, unknown>) => call<T>("POST", `/rest/v1/rpc/${fn}`, args),
    select: <T>(pathAndQuery: string) => call<T>("GET", `/rest/v1/${pathAndQuery}`),
    /** Resolves a user access token; null when it is missing, expired or invalid. */
    async getUser(jwt: string | null): Promise<AuthUser | null> {
      if (!jwt) return null;
      const res = await fetcher(`${url}/auth/v1/user`, {
        headers: { apikey: serviceKey, authorization: `Bearer ${jwt}` }, signal: AbortSignal.timeout(10_000),
      });
      if (res.status === 401 || res.status === 403) {
        await res.body?.cancel();
        return null;
      }
      if (!res.ok) throw new Error(`auth/v1/user HTTP ${res.status}`);
      const user = await res.json() as AuthUser;
      return user?.id ? user : null;
    },
    deleteUser: (id: string) => call<unknown>("DELETE", `/auth/v1/admin/users/${encodeURIComponent(id)}`),
  };
}

export type ServiceClient = ReturnType<typeof createServiceClient>;

/** Service client from the edge runtime's built-in env. */
export function serviceClientFromEnv(get: (name: string) => string | undefined): ServiceClient {
  const url = get("SUPABASE_URL"), key = get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) throw new Error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
  return createServiceClient(url, key);
}

// Refreshes fx_rates (USD per unit of each currency) from open.er-api.com: free,
// no key, ~160 currencies (every App Store currency). Runs daily from pg_cron;
// a no-op when the rates are under 6 hours old, so extra calls are harmless.
export const FX_SOURCE = "https://open.er-api.com/v6/latest/USD";
export const MIN_AGE_MS = 6 * 60 * 60 * 1000;

export type Deps = {
  lastUpdated: () => Promise<string | null>;
  upsert: (rates: Record<string, number>) => Promise<number>;
  fetcher?: typeof fetch;
  now?: () => number;
  log?: Pick<Console, "log" | "error">;
};

const reply = (status: number, body: unknown) => Response.json(body, { status });

/** Source gives units per USD; we store USD per unit. */
export function toUsdPerUnit(perUsd: Record<string, unknown>): Record<string, number> {
  const out: Record<string, number> = {};
  for (const [code, v] of Object.entries(perUsd)) {
    if (/^[A-Z]{3}$/.test(code) && typeof v === "number" && v > 0 && Number.isFinite(v)) out[code] = Number((1 / v).toPrecision(12));
  }
  return out;
}

export function createFxRefresh(deps: Deps) {
  const fetcher = deps.fetcher ?? fetch;
  const now = deps.now ?? Date.now;
  const log = deps.log ?? console;
  return async (_req: Request): Promise<Response> => {
    try {
      const last = await deps.lastUpdated();
      if (last && now() - Date.parse(last) < MIN_AGE_MS) return reply(200, { refreshed: false, updated_at: last });
      const res = await fetcher(FX_SOURCE, { signal: AbortSignal.timeout(15_000) });
      const data = await res.json() as { result?: string; rates?: Record<string, unknown> };
      if (!res.ok || data.result !== "success" || !data.rates) throw new Error(`fx source HTTP ${res.status} ${data.result ?? ""}`);
      const rates = toUsdPerUnit(data.rates);
      if (rates.USD !== 1 || Object.keys(rates).length < 100) throw new Error(`fx source returned ${Object.keys(rates).length} rates`);
      const count = await deps.upsert(rates);
      log.log("fx rates refreshed", { count });
      return reply(200, { refreshed: true, count });
    } catch (error) {
      log.error("fx refresh failed", { error: String(error) });
      return reply(502, { error: "fx refresh failed" });
    }
  };
}

